#include "profile_manager.h"
#include <assert.h>
#include <stdio.h>
#include <string.h>
int main(void){rtp_preferences p;rtp_preferences_ui nav;rtp_profile_store store;rtp_profile_manager m;rtp_pm_view v;rtp_preferences_init(&p);assert(rtp_preferences_register(&p,"connectivity","",RTP_ENTRY_CATEGORY,1,10)==RTP_PREFS_OK);assert(rtp_preferences_register(&p,"ftp","connectivity",RTP_ENTRY_SETTING,1,10)==RTP_PREFS_OK);rtp_preferences_ui_init(&nav);rtp_profiles_init(&store);assert(rtp_profiles_create(&store,"default","Default",&p)==RTP_PROFILE_OK);assert(rtp_profiles_create(&store,"work","Work",&p)==RTP_PROFILE_OK);rtp_profile_manager_init(&m,&nav,&p,&store);assert(rtp_profile_manager_open(&m)==RTP_PM_OK);assert(rtp_profile_manager_build_view(&m,&v)==RTP_PM_OK&&v.count==3&&!strcmp(v.rows[0].title,"Default")&&!strcmp(v.rows[1].title,"Work")&&v.rows[2].kind==RTP_PM_ROW_CREATE);assert(rtp_profile_manager_select(&m,"default")==RTP_PM_OK);assert(rtp_profile_manager_request_delete(&m)==RTP_PM_OK);assert(rtp_profile_manager_confirm_delete(&m,1)==RTP_PM_PROFILE_ERROR);assert(rtp_profiles_find(&store,"default")!=NULL);assert(rtp_profile_manager_back(&m)==RTP_PM_OK);assert(rtp_profile_manager_build_view(&m,&v)==RTP_PM_OK&&v.count==4&&v.rows[0].kind==RTP_PM_ROW_APPLY);assert(rtp_preferences_set_visible(&p,"ftp",0)==RTP_PREFS_OK);assert(rtp_profile_manager_apply(&m)==RTP_PM_OK);assert(rtp_preferences_find(&p,"ftp")->visible==1);assert(rtp_profile_manager_select(&m,"work")==RTP_PM_OK);assert(rtp_profile_manager_rename(&m,"Daily")==RTP_PM_OK);assert(!strcmp(rtp_profiles_find(&store,"work")->name,"Daily"));assert(rtp_profile_manager_request_delete(&m)==RTP_PM_OK);assert(rtp_profile_manager_confirm_delete(&m,0)==RTP_PM_OK);assert(rtp_profiles_find(&store,"work")!=NULL);assert(rtp_profile_manager_back(&m)==RTP_PM_OK);assert(rtp_profile_manager_select(&m,"work")==RTP_PM_OK);assert(rtp_profile_manager_request_delete(&m)==RTP_PM_OK);assert(rtp_profile_manager_confirm_delete(&m,1)==RTP_PM_OK);assert(rtp_profiles_find(&store,"work")==NULL);assert(rtp_profiles_find(&store,"default")!=NULL);assert(rtp_profile_manager_create(&m,"work","Work")==RTP_PM_OK);assert(rtp_profiles_find(&store,"work")!=NULL);assert(rtp_profile_manager_open(&m)==RTP_PM_OK);assert(rtp_profile_manager_handle_input(&m,RTP_PM_INPUT_DOWN,NULL,NULL)==RTP_PM_OK);assert(rtp_profile_manager_handle_input(&m,RTP_PM_INPUT_CONFIRM,NULL,NULL)==RTP_PM_OK);assert(m.page==RTP_PM_PAGE_PROFILE_ACTIONS);assert(rtp_profile_manager_handle_input(&m,RTP_PM_INPUT_DOWN,NULL,NULL)==RTP_PM_OK);assert(rtp_profile_manager_handle_input(&m,RTP_PM_INPUT_CONFIRM,NULL,NULL)==RTP_PM_OK);assert(rtp_profile_manager_handle_input(&m,RTP_PM_INPUT_BACK,NULL,NULL)==RTP_PM_OK);assert(rtp_profile_manager_handle_input(&m,RTP_PM_INPUT_DOWN,NULL,NULL)==RTP_PM_OK);assert(rtp_profile_manager_handle_input(&m,RTP_PM_INPUT_DOWN,NULL,NULL)==RTP_PM_OK);assert(rtp_profile_manager_handle_input(&m,RTP_PM_INPUT_CONFIRM,"test","Test")==RTP_PM_OK);assert(rtp_profiles_find(&store,"test")!=NULL);puts("Profile manager controller tests passed.");return 0;}
